 const p=await createTargetWitness(f)(f.planRequest);assert.equal(p.variantLineageHash,f.configBundle.variantLineageHash);assert.equal(f.queries,6);assert.equal(canonical(f.sourceCapture),before);assert.equal(f.configBundle.sourceEndProof.recoveryId,material.recoveryId);assert.notEqual(f.configBundle.sourceEndProof.recoveryId,effective.recoveryId);
